import { CetusTooltip } from '@cetus/design'
import { HTextLabelBox, Icon } from '@cetus/ui-kit'
import { Box, HStack, StackProps, Text, VStack } from '@chakra-ui/react'
import { useState } from 'react'

interface VaultsAprBlockProps {
  vaultsLstApyDisplay: string
  vaultsApyDisplay: string
  vaultsTotalApyDisplay: string
  vaultsAprDisplay: string
  vaultFarmingAprDisplay?: string
  category?: string
  wrapStyle?: StackProps
  isVaultsFarming?: boolean
}

function VaultsAprBlock({
  vaultsLstApyDisplay,
  vaultsApyDisplay,
  vaultsTotalApyDisplay,
  category,
  vaultsAprDisplay,
  wrapStyle,
  isVaultsFarming,
  vaultFarmingAprDisplay
}: VaultsAprBlockProps) {
  console.log('🚀🚀🚀 ~ VaultsAprBlock.tsx:27 ~ isVaultsFarming:', isVaultsFarming)
  return (
    <CetusTooltip
      tooltip={
        category == 'cetus' ? (
          <VaultsAprTooltipContentLST
            vaultsApyDisplay={vaultsApyDisplay}
            vaultsLstApyDisplay={vaultsLstApyDisplay}
            vaultsTotalApyDisplay={vaultsTotalApyDisplay}
            vaultsAprDisplay={vaultsAprDisplay}
            category={category}
          />
        ) : (
          <VaultsAprTooltipContent
            vaultsApyDisplay={vaultsApyDisplay}
            vaultsLstApyDisplay={vaultsLstApyDisplay}
            vaultsTotalApyDisplay={vaultsTotalApyDisplay}
            vaultsAprDisplay={vaultsAprDisplay}
            category={category}
            vaultFarmingAprDisplay={vaultFarmingAprDisplay}
            isVaultsFarming={isVaultsFarming}
          />
        )
      }
      placement="bottom"
      // maxW="260px"
    >
      <VStack
        gap={{
          base: '4px',
          lg: '2px'
        }}
        alignItems={{
          base: 'flex-end',
          lg: 'center'
        }}
        {...wrapStyle}
      >
        <Text textColor="text_caption" textAlign="right" fontWeight="500" textDecoration="underline dotted" color="primary">
          {category == 'cetus' ? vaultsTotalApyDisplay : vaultsApyDisplay}
        </Text>
        {isVaultsFarming && (
          <Text
            bg="primary_yellow_opacity.10"
            color="primary_yellow"
            borderRadius="4px"
            fontSize="12px"
            p={{
              base: '4px 6px',
              lg: '0 4px'
            }}
          >
            +{vaultFarmingAprDisplay}
          </Text>
        )}
      </VStack>
    </CetusTooltip>
  )
}

export const VaultsAprTooltipContentLST = ({
  vaultsLstApyDisplay,
  vaultsApyDisplay,
  vaultsTotalApyDisplay,
  category,
  vaultsAprDisplay
}: VaultsAprBlockProps) => {
  return (
    <VStack gap="12px" w="100%" pt="8px" pb="8px">
      {category == 'cetus' ? (
        <VStack>
          <HTextLabelBox
            label="Total APY"
            labelStyle={{
              fontSize: '14px'
            }}
            valueStyle={{
              fontSize: '14px'
            }}
            wrapStyle={{
              gap: '16px'
            }}
            value={vaultsTotalApyDisplay}
          />
          <HStack h="1px" w="100%" backgroundColor="border" />
          <HTextLabelBox
            label="Fees and Rewards"
            labelStyle={{
              fontSize: '12px'
            }}
            valueStyle={{
              fontSize: '12px'
            }}
            wrapStyle={{
              gap: '16px'
            }}
            value={vaultsApyDisplay}
          />
          <HTextLabelBox
            label="LST"
            labelStyle={{
              fontSize: '12px'
            }}
            wrapStyle={{
              gap: '16px'
            }}
            value={vaultsLstApyDisplay}
            valueStyle={{
              fontSize: '12px'
            }}
          />
        </VStack>
      ) : (
        <VStack>
          <HTextLabelBox
            label="Cetus LP APR"
            labelStyle={{
              fontSize: '14px'
            }}
            valueStyle={{
              fontSize: '14px'
            }}
            wrapStyle={{
              gap: '16px'
            }}
            value={vaultsAprDisplay}
          />
          <HStack h="1px" w="100%" backgroundColor="border" />
          <HTextLabelBox
            label="Vault APY"
            labelStyle={{
              fontSize: '14px'
            }}
            valueStyle={{
              fontSize: '14px'
            }}
            wrapStyle={{
              gap: '16px'
            }}
            value={vaultsApyDisplay}
          />
          <HTextLabelBox
            label="(Compounding Cetus LP APR Multiple Times a Day)"
            labelStyle={{
              fontSize: '12px',
              lineHeight: '16px',
              maxW: '200px'
            }}
            wrapStyle={{
              gap: '16px'
            }}
            value=""
            valueStyle={{
              fontSize: '12px'
            }}
          />
        </VStack>
      )}
    </VStack>
  )
}

export const VaultsAprTooltipContent = ({
  vaultsLstApyDisplay,
  vaultsApyDisplay,
  vaultsTotalApyDisplay,
  category,
  vaultsAprDisplay,
  vaultFarmingAprDisplay,
  isVaultsFarming
}: VaultsAprBlockProps) => {
  const [accessHover, setAccessHover] = useState(false)
  return (
    <VStack
      w="250px"
      onClick={e => {
        e.stopPropagation()
      }}
    >
      <VStack bg="bg_fifth" borderRadius="8px" p="12px 16px" gap="10px">
        <HTextLabelBox label="Cetus LP APR" value={vaultsAprDisplay} labelStyle={{ fontSize: '12px' }} valueStyle={{ fontSize: '12px' }} />
        <Box m="8px 0" height="1px" w="100%" bg="border" />
        <HTextLabelBox label="Vault APY" value={vaultsApyDisplay} />
        <Text fontSize="12px" lineHeight="20px">
          (Compounding Cetus LP APR Multiple Times a Day)
        </Text>
      </VStack>
      {isVaultsFarming && (
        <VStack w="100%" bg="primary_yellow_opacity.10" borderRadius="8px" p="12px 16px" gap="10px" alignItems="flex-start">
          <Text color="text_caption" fontSize="12px">
            Farming Rewards Available
          </Text>
          <Text mt="4px" color="primary_yellow" fontSize="12px">
            Farming APR +{vaultFarmingAprDisplay}
          </Text>
          <HStack
            cursor="pointer"
            onMouseMove={() => {
              setAccessHover(true)
            }}
            onMouseLeave={() => {
              setAccessHover(false)
            }}
            gap="0"
            onClick={e => {
              e.stopPropagation()
              window.open('https://www.haedal.xyz/farms', '_blank')
            }}
          >
            <Text color={accessHover ? 'text_caption' : 'text_paragraph'} fontSize="12px">
              Access
            </Text>
            <Icon xlinkHref="#icon-icon_ascending_nor" transform="rotate(90deg)" svgFill={accessHover ? 'text_caption' : 'text_paragraph'} />
          </HStack>
        </VStack>
      )}
    </VStack>
  )
}

export default VaultsAprBlock
