import { aprProcessing } from '@/utils/api-data-utils'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import { d } from '@cetusprotocol/common-sdk'

export default function useGetVaultsFarmingApr(vaultsFarmsReward: any) {
  const { getTokenAmountValue } = useTokenPrice()

  const getVaultsFarmingApr = () => {
    if (!vaultsFarmsReward) return { vaultFarmingAprDisplay: '' }
    const { farmingPoolAmountA, farmingPoolAmountB, coinTypeA, coinTypeB, rewardList } = vaultsFarmsReward
    console.log('🚀🚀🚀 ~ useGetVaultsFarmingApr.tsx:12 ~ getVaultsFarmingApr ~ vaultsFarmsReward:', vaultsFarmsReward)
    const farmingPoolAmountAUSD = getTokenAmountValue(coinTypeA, farmingPoolAmountA)
    console.log('🚀🚀🚀 ~ useGetVaultsFarmingApr.tsx:15 ~ getVaultsFarmingApr ~ coinTypeA, farmingPoolAmountA:', coinTypeA, farmingPoolAmountA)
    const farmingPoolAmountBUSD = getTokenAmountValue(coinTypeB, farmingPoolAmountB)
    console.log('🚀🚀🚀 ~ useGetVaultsFarmingApr.tsx:17 ~ getVaultsFarmingApr ~ coinTypeB, farmingPoolAmountB:', coinTypeB, farmingPoolAmountB)
    const farmingTvl = d(farmingPoolAmountAUSD).add(farmingPoolAmountBUSD)
    let totalRewardUSD = d(0)
    for (let i = 0; i < rewardList.length; i++) {
      const item = rewardList[i]
      totalRewardUSD = totalRewardUSD.add(getTokenAmountValue(item.rewardCoinType, item.rewardItemRate))
    }
    console.log('🚀🚀🚀 ~ useGetVaultsFarmingApr.tsx:18 ~ getVaultsFarmingApr ~ totalRewardUSD:', totalRewardUSD.toString(), farmingTvl.toString())
    const vaultFarmingApr = totalRewardUSD.div(farmingTvl).mul(365).toString()
    if (totalRewardUSD.toString() == '0') {
      return { vaultFarmingAprDisplay: '' }
    }
    return {
      vaultFarmingApr,
      vaultFarmingAprDisplay: aprProcessing(vaultFarmingApr, true)
    }
  }
  return { getVaultsFarmingApr }
}
